(function(){
 'use strict';
 const E=window.IslandMath,D=window.IslandData,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number.isFinite(n)?n.toLocaleString('ru-RU',{maximumFractionDigits:1}):'—';
 const uid=()=>crypto.randomUUID(),input=(label,id,value='',max=1e12,step='0.01')=>'<label class="field">'+label+'<input id="'+id+'" type="number" min="0" max="'+max+'" step="'+step+'" value="'+value+'"></label>',select=(label,id,options)=>'<label class="field">'+label+'<select id="'+id+'">'+options+'</select></label>',opt=(value,label)=>'<option value="'+esc(value)+'">'+esc(label)+'</option>';
 const cities=E.cities.map(c=>opt(c,c)).join(''),panel=document.createElement('section');panel.id='island-content';panel.className='activity-content island-content';panel.hidden=true;
 panel.innerHTML='<div class="panel island-manager"><div class="section-heading"><h2>Мои острова</h2><span class="tag">ОСТРОВ</span></div><div class="grid2">'+select('Сохранённый остров','island-picker','')+'<label class="field">Название нового острова<input id="island-name" maxlength="60" placeholder="Например, огород альта"></label></div><div class="island-actions"><button class="button primary" id="island-add">Новый остров</button><button class="button" id="island-copy">Скопировать план</button><button class="button" id="island-rename">Переименовать</button><button class="button" id="island-delete">Удалить остров</button></div><p class="hint">До 20 планов на каждом сервере. Копия содержит настройки и цены, а фактический журнал начинается пустым.</p><p id="island-message" role="status" aria-live="polite" class="hint"></p></div>'+
 '<div class="flow-layout"><div class="flow-steps"><section class="step-card"><div class="section-heading"><h2>1. Остров и период</h2></div><div class="grid2">'+select('Город острова / закупки','island-city',cities)+select('Рынок продажи','island-sellCity',cities)+'</div><div class="grid2">'+input('Доступных участков всего','island-plots',16,10000,'1')+input('Период, дней','island-days',30,3650,'1')+'</div><div class="grid2">'+input('Часов между сборами','island-interval',24,720,'1')+input('Домов для рабочих','island-houses',0,10000,'1')+'</div>'+input('Мест для рабочих в одном доме','island-slots',3,10000,'1')+'<label class="refining-check"><input id="island-premium" type="checkbox"> Есть премиум: двойной урожай</label><p class="hint">Одна грядка — 9 растений. Дома, грядки и пастбища используют общий лимит участков. Укажите реальные участки и вместимость ваших домов; по умолчанию расчёт для личного острова с домами на 3 рабочих. Сбор раз в сутки; рост растений — 22 часа.</p></section>'+
 '<section class="step-card"><div class="section-heading"><h2>2. Грядки и травы</h2><button class="button" id="island-add-crop">+ Грядки</button></div><div id="island-crops"></div><p class="hint" id="island-character-note"></p><p class="hint">Полив увеличивает возврат семян. Урожай и семена показаны как среднее за много сборов; случайный недобор требует запаса. Семена для следующей посадки сохраняются, продаётся только избыток. Черви в прогноз дохода не включены.</p></section>'+
 '<section class="step-card"><div class="section-heading"><h2>3. Рабочие</h2><button class="button" id="island-add-worker">+ Рабочие</button></div><div id="island-workers"></div><p class="hint">По одному полному журналу на рабочего за цикл. Введите процент доходности из окна рабочего: приложение не предполагает максимальное счастье. Премиум аккаунта влияет здесь только на грядки.</p></section>'+
 '<section class="step-card"><div class="section-heading"><h2>4. Животноводство</h2><button class="button" id="island-add-animal">+ Животные</button></div><div id="island-animals"></div><p class="hint">Пастбище вмещает до 9 животных и использует общий участок острова. Молодняк растёт 22 часа с премиумом и 44 без него. Для молока и яиц покупаем взрослых либо используем уже имеющихся. Суммы наград и потомства — средние значения.</p></section>'+
 '<section class="step-card"><h2>5. Расходы и вложения</h2>'+select('Способ продажи','island-saleMode',opt('order','Выставить ордер продажи')+opt('instant','Продать сразу в ордер покупки'))+'<div class="grid2">'+input('Налог продажи, %','island-tax',4,100)+input('Выставление ордера, %','island-setup',2.5,100)+'</div><div class="grid2">'+input('Доставка за сбор','island-transport',0)+input('Другие расходы за сбор','island-other',0)+'</div>'+input('Доля премиума, серебро / день','island-premiumDaily',0)+'<details class="fold"><summary>Фокус и оценка своего времени</summary><div class="grid2">'+input('Фокус на полив и уход при запуске','island-focusBudget',10000,3000000,'1')+input('Цена упущенной выгоды / 1 фокус','island-focusValue',0)+'</div><p class="hint">Оценка фокуса уменьшает экономическую прибыль, но не считается денежным платежом. Введите доступный фокус именно на этот сбор.</p></details><details class="fold" open><summary>Первоначальные вложения</summary><p class="hint">Укажите только новые платежи. Уже купленный остров и мебель повторно не списываются. Цены покупки и улучшений меняются — заполните свои суммы. Нулевые значения ниже не означают бесплатный остров.</p><div class="grid2">'+input('Покупка и улучшения острова','island-cap-island',0)+input('Постройка и улучшения домов','island-cap-houses',0)+input('Кровати, столы и трофеи','island-cap-furniture',0)+input('Контракты рабочих','island-cap-contracts',0)+input('Грядки, сады и пастбища','island-cap-farms',0)+input('Другие вложения','island-cap-other',0)+'</div></details></section></div>'+
 '<aside class="outcome panel island-outcome"><span class="eyebrow">ДОХОДНОСТЬ ОСТРОВА</span><p id="island-readiness" role="status" aria-live="polite"></p><div class="metrics"><div class="metric profit"><span>ПРИБЫЛЬ ЗА ДЕНЬ</span><strong id="island-day-profit">—</strong><small>После текущих расходов и доли премиума</small></div><div class="metric"><span>ПРИБЫЛЬ ЗА ПЕРИОД</span><strong id="island-period-profit">—</strong><small id="island-period-note"></small></div><div class="metric"><span>СТАРТОВЫЕ ВЛОЖЕНИЯ</span><strong id="island-investment">—</strong><small>Строительство + начальный запас</small></div><div class="metric"><span>ОКУПАЕМОСТЬ</span><strong id="island-payback">—</strong><small id="island-roi"></small></div></div><dl class="island-totals" id="island-totals"></dl><p id="island-warnings" class="hint"></p><p class="hint">Окупаемость — оценка при стабильных ценах и регулярных сборах. Неподтверждённые цены блокируют итог. Расходы закупки берутся из города острова; продажа — из выбранного рынка.</p><button class="button" id="island-export">Экспорт расчёта CSV</button><button class="button" id="island-to-actual">Записать фактический результат ↓</button></aside></div>'+
 '<section class="panel island-breakdown"><h2>Доходы и расходы производства</h2><div class="table-scroll"><table><thead><tr><th>Источник</th><th>Выручка</th><th>Закупки</th><th>Комиссии</th><th>Прибыль</th><th>Выход / количество</th></tr></thead><tbody id="island-breakdown"></tbody></table></div><p class="hint">Строки показывают доход и затраты за собственный цикл: грядки и рабочие — по общему интервалу, животные — по интервалу группы. Общие суммы приводятся к интервалу грядок и рабочих; за период учитываются только завершённые циклы каждой группы. Доставка и прочие расходы задаются за общий интервал. Урожай и награды рабочих — ожидаемые значения, а не гарантированная партия.</p><details class="fold"><summary>Рыночные и ручные цены</summary><p class="hint">Автоцены проверяются на свежесть и выбросы. Для продажи нужна история ≥3 дней, ≥1 шт. в день, не старше 72 часов. Ручная цена заменяет рынок только для этого города и сервера. Пустое поле возвращает автоцену. Комиссия применяется к продажам ресурсов и пустых журналов; прямое серебро наёмника не облагается.</p><div id="island-price-list"></div><p id="island-market-status" role="status" class="hint"></p></details><details class="fold"><summary>Сравнить сохранённые острова</summary><div class="table-scroll"><table><thead><tr><th>Остров</th><th>Прибыль / день</th><th>Вложения</th><th>Окупаемость</th><th>Готовность</th></tr></thead><tbody id="island-compare"></tbody></table></div><p class="hint">Прогнозы используют свои города, настройки и ручные цены. Обновление рынка загружает цены всех сохранённых островов выбранного сервера.</p></details></section>'+
 '<section class="panel island-actual" id="island-actual"><h2>Фактические доходы и затраты</h2><p class="hint">Записывайте только реальные продажи и платежи. Полученные ресурсы на складе ещё не доход; старый запас без новой покупки не платёж. Стартовые вложения указывайте один раз по факту. Для достоверного результата заносите все расходы за выбранный период, включая премиум. Эти записи независимы от прогноза.</p><form id="island-actual-form"><div class="grid2"><label class="field">Дата<input type="date" id="island-actual-date" required></label><label class="field">Описание<input id="island-actual-note" maxlength="120" placeholder="Урожай, рабочие или покупка острова"></label></div><div class="grid2">'+input('Выручка до комиссий','island-actual-income',0)+input('Покупка семян / журналов / материалы','island-actual-supplies',0)+input('Фактически уплаченные комиссии','island-actual-fees',0)+input('Доставка','island-actual-transport',0)+input('Прочие расходы, в том числе премиум','island-actual-other',0)+input('Новые вложения в остров и оборудование','island-actual-investment',0)+'</div><button class="button primary" type="submit">Добавить запись</button></form><div class="grid2 island-date-filter"><label class="field">Показать с<input id="island-actual-from" type="date"></label><label class="field">По дату<input id="island-actual-to" type="date"></label></div><div id="island-actual-summary" class="activity-summary"></div><div class="table-scroll"><table><thead><tr><th>Дата / описание</th><th>Выручка</th><th>Текущие расходы</th><th>Вложения</th><th>Чистый поток</th><th></th></tr></thead><tbody id="island-ledger"></tbody></table></div><p id="island-actual-comparison" class="hint"></p><button class="button" id="island-actual-export">Экспорт фактических результатов CSV</button></section>'+
 '<details class="source-info"><summary>Правила и источники расчёта</summary><p>Культуры, возврат семян и состав наград: <a href="https://github.com/ao-data/ao-bin-dumps" target="_blank" rel="noopener">игровые данные Albion</a>, проверено 12 октября 2026. Средний базовый урожай 4,5 с растения; премиум удваивает урожай. Бонус подходящего города +10% применяется к урожаю, не к семенам. Дробные значения — ожидание за много циклов. Рыночный объём и случайные недоборы не гарантированы.</p><p><a href="https://albiononline.com/news/guide-farming" target="_blank" rel="noopener">Официальное руководство по фермерству</a> · <a href="https://albiononline.com/update/wild-blood" target="_blank" rel="noopener">Общие участки и местные бонусы</a>. Фокус для полива вводится отдельно для выбранного персонажа: мастерства крафта к нему не применяются. Запас для следующей посадки и пустые журналы при самостоятельном заполнении остаются в обороте. Лишние непроданные семена не включены в выручку. Собственное время и фокус учитываются только в экономической прибыли.</p></details>';
 document.querySelector('footer').before(panel);
 let store,plan,result,active=false,oldServer,ticket=0,storeError='';const market=window.FeatureMarket.create(),state={server:'europe'};
 try{store=E.createStore(localStorage,D);}catch(error){storeError=error.message;}
 const current=()=>{const s=store.snapshot(state.server);return s.plans.find(x=>x.uid===s.active);};
 const profile=()=>window.CharacterProfiles?.snapshot().active||'default';
 function message(text){$('island-message').textContent=text;}
 function read(){plan=current().plan;}
 function save(){try{store.save(state.server,plan);message('Настройки острова сохранены.');return true;}catch(error){message(error.message+' Изменения не сохранены.');return false;}}
 function quote(id,side,city,saleMode=plan.saleMode){const q=market.quote(state.server,id,city,1,side==='sell'&&saleMode==='instant',side==='sell'),h=market.history(state.server,id,city,1);if(side==='sell'&&!q.manual&&!(h?.days>=3&&h.daily>=1&&window.MarketGuard.age(h.to+'T23:59:59Z')<=72))return {...q,price:0,reason:'Нет свежего объёма продаж'};return q;}
 const calc=p=>E.calculate(p,D,quote,profile());
 function rowField(label,group,r,key,value,max=1e12,step='0.01'){return '<label class="field">'+label+'<input type="number" min="0" max="'+max+'" step="'+step+'" data-island-group="'+group+'" data-uid="'+r.uid+'" data-field="'+key+'" value="'+esc(value??'')+'"></label>';}
 function rowSelect(label,group,r,key,options,value){return '<label class="field">'+label+'<select data-island-group="'+group+'" data-uid="'+r.uid+'" data-field="'+key+'">'+options.map(([v,n])=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label>';}
 function rows(){
  $('island-crops').innerHTML=plan.crops.map(r=>{const c=D.crops.find(x=>x.id===r.id),f=plan.focusCosts[profile()+'|'+r.id]??c.focus;return '<article class="island-group"><div class="section-heading"><b>Грядки · '+esc(c.name)+'</b><button class="button" data-remove-group="crops" data-uid="'+r.uid+'">Убрать</button></div>'+rowSelect('Культура','crops',r,'id',D.crops.map(c=>[c.id,'T'+c.tier+' '+c.name]),r.id)+'<div class="grid2">'+rowField('Грядок / участков','crops',r,'plots',r.plots,10000,'1')+rowField('Поливаемых растений из '+r.plots*9,'crops',r,'water',r.water,r.plots*9,'1')+rowField('Семян уже в запасе','crops',r,'stock',r.stock,90000,'1')+rowField('Фокус / растение для этого персонажа','crops',r,'focus',f,1000,'1')+'</div><label class="refining-check"><input type="checkbox" data-island-group="crops" data-uid="'+r.uid+'" data-field="sellSeeds" '+(r.sellSeeds?'checked':'')+'> Продавать избыток семян</label><p class="hint">Возврат без полива '+fmt(c.seedReturn*100)+'%; с поливом '+fmt((c.seedReturn+c.wateringBonus)*100)+'%. '+(c.bonusCities.includes(plan.city)?'В этом городе урожай +10%.':'В этом городе нет бонуса этой культуре.')+'</p></article>';}).join('')||'<p class="hint">Добавьте грядки с овощами или травами.</p>';
  $('island-workers').innerHTML=plan.workers.map(r=>{const j=D.journals.find(x=>x.id===r.id);return '<article class="island-group"><div class="section-heading"><b>Рабочие · T'+j.tier+' '+esc(j.name)+'</b><button class="button" data-remove-group="workers" data-uid="'+r.uid+'">Убрать</button></div>'+rowSelect('Профессия и тир журнала','workers',r,'id',D.journals.map(j=>[j.id,'T'+j.tier+' '+j.name]),r.id)+'<div class="grid2">'+rowField('Рабочих','workers',r,'count',r.count,10000,'1')+rowField('Доходность из окна рабочего, %','workers',r,'yield',r.yield,150)+'</div>'+rowSelect('Как получаем полные журналы','workers',r,'mode',[['buy','Покупаем; пустые продаём'],['self','Заполняем сами; пустые используем снова']],r.mode)+(r.mode==='self'?'<div class="grid2">'+rowField('Пустых журналов уже в запасе','workers',r,'stock',r.stock,10000,'1')+rowField('Реальные расходы заполнения / журнал','workers',r,'fillCost',r.fillCost)+rowField('Дополнительная оценка своего времени / журнал','workers',r,'fillValue',r.fillValue)+'</div><p class="hint">Пустые журналы покупаются только для стартового запаса. Заполняемые самим журналы тоже требуют времени: укажите расходы и дополнительную упущенную выгоду.</p>':'<p class="hint">В расходах полная цена заполненного журнала; возвращённый пустой журнал продаётся с комиссией.</p>')+(j.rewards.length?rowField('Стоимость всей награды ресурсами при 100%, до налога','workers',r,'reward',r.reward)+'<p class="hint">Оставьте пустым для оценки по составу награды и рынку. Ручная сумма — ресурсы одного рабочего при доходности 100%, затем применяется ваш процент.</p>':'<p class="hint">Прямое серебро при 100%: '+fmt(j.silver)+' / журнал. Это ожидание, выплата случайна.</p>')+'</article>';}).join('')||'<p class="hint">Добавьте рабочих и выберите журналы.</p>';
  const profiles=window.CharacterProfiles?.snapshot(),character=profiles?.profiles.find(p=>p.id===profiles.active)?.name||'Основной персонаж';$('island-character-note').textContent='Полив: '+character+'. Стоимость фокуса сохранена отдельно для каждого персонажа и культуры. Пока значение не введено, используется базовая стоимость 1000; укажите стоимость из игры.';
  animalRows();
 }
 function animalRows(){
  $('island-animals').innerHTML=plan.animals.map(r=>{const a=D.animals.find(a=>a.id===r.id),v=E.animalParameters(r,plan,D,profile()),f=plan.focusCosts[profile()+'|'+r.id]??a.focus,modes=[['grown','Вырастить и продать взрослое животное'],['meat','Вырастить и разделать на мясо']];if(a.product)modes.push(['produce','Держать взрослых: '+a.product.name]);return '<article class="island-group"><div class="section-heading"><b>'+esc(a.name)+'</b><button class="button" data-remove-group="animals" data-uid="'+r.uid+'">Убрать</button></div>'+rowSelect('Животные','animals',r,'id',D.animals.map(a=>[a.id,'T'+a.tier+' '+a.name]),r.id)+rowSelect('Источник дохода','animals',r,'mode',modes,r.mode)+'<div class="grid2">'+rowField('Пастбищ / участков','animals',r,'plots',r.plots,10000,'1')+rowField('Животных всего, до 9 на пастбище','animals',r,'count',r.count,90000,'1')+rowField(r.mode==='produce'?'Взрослых животных уже в наличии':'Молодняка уже в наличии','animals',r,'stock',r.stock,90000,'1')+rowField('Часов между сборами этой группы','animals',r,'interval',r.interval,720,'1')+'</div>'+rowSelect('Корм','animals',r,'feed',D.crops.filter(c=>c.kind==='crop').map(c=>[c.id,c.name+(c.id===a.favorite?' · любимый корм':'')]),r.feed)+rowField('Фактический корм / животное за весь цикл','animals',r,'feedQty',r.feedQty)+'<p class="hint">Автоматический корм: '+fmt(v.feedQty)+' шт. на животное за цикл; пустое поле использует расчёт по питательности. Любимый корм: '+esc(D.crops.find(c=>c.id===a.favorite).name)+'. Продажа урожая и покупка корма считаются отдельными сделками.</p>'+(r.mode==='produce'?rowField('Фактический средний выход молока / яиц на животное','animals',r,'productYield',r.productYield)+'<p class="hint">Автоматический выход: '+fmt(v.productYield)+' / животное. Пустое поле использует премиум и местный бонус. Покупка взрослых — стартовое вложение, корм — каждый цикл; взрослые остаются на острове. Потомство и фокус при этом не начисляются.</p>':'<div class="grid2">'+rowField('Животных с уходом за фокус','animals',r,'nurture',r.nurture,r.count,'1')+rowField('Фокус / уход для этого персонажа','animals',r,'focus',f,1000,'1')+'</div><label class="refining-check"><input type="checkbox" data-island-group="animals" data-uid="'+r.uid+'" data-field="sellBabies" '+(r.sellBabies?'checked':'')+'> Продавать лишний молодняк</label><p class="hint">Потомство без ухода: '+fmt(a.offspring*100)+'%; с уходом: '+fmt((a.offspring+a.nurtureBonus)*100)+'%. Молодняк для следующей партии сохраняется, недостающее количество докупается. Базовая стоимость ухода — 1000 фокуса; введите стоимость выбранного персонажа из игры.</p>')+(r.mode==='meat'?'<div class="grid2">'+rowField('Фактическое мясо / животное после разделки','animals',r,'meatYield',r.meatYield)+rowField('Станок и разделка / животное','animals',r,'butcherCost',r.butcherCost)+'</div><p class="hint">Базовый выход — 18 мяса. Укажите выход и плату выбранного мясника с учётом его бонусов; городской бонус грядок не подменяет бонус станка. Фокус разделки учитывайте в отдельном расчёте крафта.</p>':'')+'<p class="hint">Минимальный цикл: '+fmt(v.growth)+' ч. Расчётный цикл: '+fmt(v.hours)+' ч. Завершённых циклов за период: '+v.cycles+'. Если заданный интервал короче роста, применяется время роста.</p></article>';}).join('')||'<p class="hint">Добавьте кур, коз, гусей, овец, свиней или коров.</p>';
 }
 function priceItems(p){const items=new Map(),add=(id,side,city,name)=>items.set([city,side,id].join('|'),{id,side,city,name});for(const r of p.crops){if(!r.plots)continue;const c=D.crops.find(x=>x.id===r.id);if(r.stock<r.plots*9||r.plots*9*c.seedReturn+r.water*c.wateringBonus<r.plots*9)add(c.seed,'buy',p.city,'Семена: '+c.name);add(c.id,'sell',p.sellCity,c.name);if(r.sellSeeds&&r.plots*9*c.seedReturn+r.water*c.wateringBonus>r.plots*9)add(c.seed,'sell',p.sellCity,'Избыток семян: '+c.name);}for(const r of p.workers){if(!r.count)continue;const j=D.journals.find(x=>x.id===r.id);if(r.mode==='buy'){add(j.filled,'buy',p.city,'Полный журнал: T'+j.tier+' '+j.name);add(j.empty,'sell',p.sellCity,'Пустой журнал: T'+j.tier+' '+j.name);}else if(r.stock<r.count)add(j.empty,'buy',p.city,'Пустой журнал: T'+j.tier+' '+j.name);if(r.reward===null)for(const x of j.rewards)add(x.id,'sell',p.sellCity,x.name);}for(const r of p.animals){if(!r.count)continue;const a=D.animals.find(a=>a.id===r.id),v=E.animalParameters(r,p,D,profile());if(v.feedQty>0)add(r.feed,'buy',p.city,'Корм: '+D.crops.find(c=>c.id===r.feed).name);if(r.mode==='produce'){if(r.stock<r.count)add(a.grown,'buy',p.city,'Взрослые: '+a.name);add(a.product.id,'sell',p.sellCity,a.product.name);}else{const babies=r.count*a.offspring+r.nurture*a.nurtureBonus;if(r.stock<r.count||babies<r.count)add(a.id,'buy',p.city,'Молодняк: '+a.name);if(r.sellBabies&&babies>r.count)add(a.id,'sell',p.sellCity,'Избыток молодняка: '+a.name);add(r.mode==='meat'?a.meat:a.grown,'sell',p.sellCity,r.mode==='meat'?'Мясо: '+a.name:'Взрослые: '+a.name);}}return items;}
 function prices(){const items=priceItems(plan);$('island-price-list').innerHTML='<div class="table-scroll"><table><thead><tr><th>Предмет / город</th><th>Действие</th><th>Рынок / источник</th><th>Ручная цена</th></tr></thead><tbody>'+[...items].map(([key,v])=>{const q=quote(v.id,v.side,v.city),manual=Object.hasOwn(plan.prices,key);return '<tr><td>'+esc(v.name)+'<small class="island-item-id">'+esc(v.city)+' · '+esc(v.id)+'</small></td><td>'+(v.side==='buy'?'Купить':plan.saleMode==='instant'?'Продать сразу':'Ордер продажи')+'</td><td>'+(q.price>0?fmt(q.price)+' · '+fmt(q.age)+' ч.':esc(q.reason||'Нет подтверждённой цены'))+(manual?'<small class="island-item-id">В расчёте ручная цена</small>':'')+'</td><td><input type="number" min="0" step="0.01" data-island-price="'+esc(key)+'" value="'+(manual?plan.prices[key]:'')+'" placeholder="'+(q.price>0?fmt(q.price):'Введите цену')+'" aria-label="Цена '+esc(v.name)+' '+esc(v.city)+'"></td></tr>';}).join('')+'</tbody></table></div>'+(items.size?'':'<p class="hint">Цены появятся после добавления производства.</p>');}
 function ledgerEntries(){const from=$('island-actual-from').value,to=$('island-actual-to').value;return plan.ledger.filter(x=>(!from||x.date>=from)&&(!to||x.date<=to));}
 function ledger(){const entries=ledgerEntries(),x=E.actual(entries);$('island-actual-summary').innerHTML=[['Выручка',x.income],['Фактические текущие затраты',x.costs],['Операционная прибыль',x.profit],['Вложения',x.investment],['Чистый денежный поток',x.netCash]].map(([label,v])=>'<div class="panel"><span>'+label+'</span><h3>'+fmt(v)+'</h3></div>').join('');$('island-ledger').innerHTML=[...entries].reverse().map(e=>{const t=E.actual([e]);return '<tr><td>'+esc(e.date)+'<small class="island-item-id">'+esc(e.note)+'</small></td><td>'+fmt(e.income)+'</td><td>'+fmt(t.costs)+'</td><td>'+fmt(e.investment)+'</td><td>'+fmt(t.netCash)+'</td><td><button class="button" data-remove-entry="'+esc(e.uid)+'">Удалить</button></td></tr>';}).join('')||'<tr><td colspan="6">Нет записей за выбранный период.</td></tr>';
  const from=$('island-actual-from').value,to=$('island-actual-to').value;let text='Прогноз и фактический журнал не смешиваются. Выберите даты, чтобы сопоставить прибыль.';if(from&&to&&from<=to&&result?.ready){const days=Math.round((Date.parse(to)-Date.parse(from))/86400000)+1,forecast=calc({...plan,days:Math.min(days,3650)});text='Прогноз за '+Math.min(days,3650)+' дней при текущих настройках: '+fmt(forecast.profit)+'. Фактическая операционная прибыль: '+fmt(x.profit)+'. Отклонение: '+fmt(x.profit-forecast.profit)+'. Проверьте полноту записей.';}if(from&&to&&from>to)text='Начальная дата должна быть не позже конечной.';$('island-actual-comparison').textContent=text;
 }
 function results(){try{result=calc(plan);}catch(error){result=null;$('island-readiness').textContent=error.message;for(const id of ['day-profit','period-profit','investment','payback'])$('island-'+id).textContent='—';$('island-totals').textContent='';$('island-breakdown').textContent='';$('island-export').disabled=true;return;}
  const x=result,ready=x.ready;$('island-readiness').textContent=ready?'Расчёт готов':'Проверьте данные';$('island-readiness').className=ready?'result-status':'hint';$('island-day-profit').textContent=ready?fmt(x.perDay):'—';$('island-period-profit').textContent=ready?fmt(x.profit):'—';$('island-investment').textContent=ready?fmt(x.investment):'—';$('island-payback').textContent=ready?(x.payback===null?(x.investment===0?'Нет новых вложений':'Не окупается'):x.payback+' дней'):'—';$('island-period-note').textContent=plan.days+' дней · '+x.cycles+' сборов по общему интервалу; животные — по своим циклам';$('island-roi').textContent=ready&&x.roi!==null?'Прибыль за период / вложения: '+fmt(x.roi)+'%':'';
  const totals=[['Выручка за общий интервал',x.gross],['Комиссии за общий интервал',x.fees],['Семена, журналы, корм и разделка',x.supplies],['Текущие затраты за общий интервал',x.cost],['Начальный запас семян',x.seedCapital],['Начальный запас пустых журналов',x.journalCapital],['Молодняк / взрослые для старта',x.animalCapital],['Строительство и оборудование',x.capex],['Нужно денег к первому запуску¹',x.requiredCash],['Денежный итог периода²',x.netCash],['Экономическая прибыль периода³',x.economicProfit],['Фокус на полив и уход при запуске',x.focus]];
  $('island-totals').innerHTML=totals.map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+(ready?fmt(v):'—')+'</dd></div>').join('');$('island-warnings').textContent=[...x.errors,...(x.missing.length?['Нет цен: '+x.missing.slice(0,8).join(', ')+(x.missing.length>8?' и ещё '+(x.missing.length-8):'')]:[]),'Участки: '+x.usedPlots+' / '+plan.plots+'. Рабочие: '+x.workers+' / '+plan.houses*plan.slots+'.','¹ Вложения плюс запас денег на первые текущие закупки. Этот запас не списывается второй раз. ² Прибыль минус стартовые вложения, остатки не распродаются. ³ Дополнительно вычтена оценка фокуса и собственного времени.',x.retainedBabies>0?'Лишний молодняк в запасе: '+fmt(x.retainedBabies)+', в доход не включён.':'',x.retainedSeeds>0?'Избыток семян на складе: '+fmt(x.retainedSeeds)+' за сбор, в доход не включён.':''].filter(Boolean).join(' ');
  $('island-breakdown').innerHTML=x.rows.map(r=>'<tr><td>'+esc(r.name)+(r.kind==='animal'?'<small class="island-item-id">Цикл '+fmt(r.hours)+' ч. · '+r.cycles+' циклов за период · корм: '+fmt(r.foodQty)+' · потомство: '+fmt(r.offspring)+'</small>':r.kind==='crop'?'<small class="island-item-id">Семян: '+fmt(r.seeds)+' · докупка: '+fmt(r.deficit)+' · избыток: '+fmt(r.surplus)+'</small>':'<small class="island-item-id">Ресурсы: '+fmt(r.resources)+' · серебро: '+fmt(r.silver)+' · пустые журналы: '+fmt(r.emptySales)+'</small>')+'</td><td>'+(r.ready?fmt(r.gross):'—')+'</td><td>'+(r.ready?fmt(r.cost):'—')+'</td><td>'+(r.ready?fmt(r.fees):'—')+'</td><td>'+(r.ready?fmt(r.profit):'—')+'</td><td>'+fmt(r.output??r.harvest??r.count)+'</td></tr>').join('')||'<tr><td colspan="6">Добавьте производство.</td></tr>';
  $('island-compare').innerHTML=store.snapshot(state.server).plans.map(p=>{try{const v=calc(p.plan);return '<tr><td>'+esc(p.name)+'</td><td>'+(v.ready?fmt(v.perDay):'—')+'</td><td>'+(v.ready?fmt(v.investment):'—')+'</td><td>'+(v.ready?(v.payback!==null?v.payback+' дн.':v.investment===0?'Нет вложений':'Не окупается'):'—')+'</td><td>'+(v.ready?'Готов':'Нужны данные')+'</td></tr>';}catch{return '<tr><td>'+esc(p.name)+'</td><td colspan="4">Проверьте параметры</td></tr>';}}).join('');$('island-export').disabled=!ready;ledger();
 }
 function render(){if(!store){message(storeError);panel.querySelectorAll('input,button,select').forEach(n=>n.disabled=true);return;}read();const s=store.snapshot(state.server);$('island-picker').innerHTML=s.plans.map(p=>opt(p.uid,p.name)).join('');$('island-picker').value=s.active;$('island-delete').disabled=s.plans.length<2;$('island-add').disabled=$('island-copy').disabled=s.plans.length>=20;for(const key of ['city','sellCity','saleMode','plots','houses','slots','days','interval','tax','setup','transport','other','premiumDaily','focusBudget','focusValue'])$('island-'+key).value=plan[key];$('island-premium').checked=plan.premium;$('island-setup').disabled=plan.saleMode==='instant';for(const key of Object.keys(plan.capital))$('island-cap-'+key).value=plan.capital[key];rows();prices();results();}
 async function refresh(force){if(!store||!active)return;const n=++ticket,server=state.server,ids=[...new Set(store.snapshot(server).plans.flatMap(p=>[...priceItems(p.plan).values()].map(v=>v.id)))];$('island-market-status').textContent='Загружаем цены и историю…';try{const status=await market.load(server,ids,force);if(n!==ticket||!active||server!==state.server)return;$('island-market-status').textContent=status||'Проверка рынка завершена. Для редких предметов может понадобиться ручная цена.';prices();results();}catch(error){if(n===ticket&&active)$('island-market-status').textContent='Не удалось обновить цены: '+error.message;}}
 const view={panel,market,state,active:()=>active,render,refresh,activate(){active=true;oldServer=$('server').value;state.server=oldServer;$('craft-content').hidden=true;panel.hidden=false;document.querySelectorAll('button.nav[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode==='island'));render();refresh(false);},deactivate(){if(!active)return;active=false;ticket++;market.cancel();panel.hidden=true;$('craft-content').hidden=false;$('server').value=oldServer;$('refresh').disabled=false;$('refresh').textContent='↻ Обновить цены';}};
 window.ActivityViews.island=view;
 function mutate(action,repaint=true,reload=false){if(!store)return;const before=JSON.parse(JSON.stringify(plan));try{action();E.validate(plan,D);store.save(state.server,plan);message('Настройки острова сохранены.');if(repaint){if(reload)render();else{rows();prices();results();}}else results();$('island-setup').disabled=plan.saleMode==='instant';}catch(error){plan=before;render();message(error.message+' Изменения не сохранены.');}}
 $('island-add-crop').onclick=()=>{if(plan.crops.length>=30)return message('Не больше 30 групп грядок.');mutate(()=>plan.crops.push({uid:uid(),id:'T1_CARROT',plots:1,water:0,stock:0,sellSeeds:true}));refresh(false);};
 $('island-add-animal').onclick=()=>{if(plan.animals.length>=30)return message('Не больше 30 групп животных.');mutate(()=>plan.animals.push({uid:uid(),id:'T3_FARM_CHICKEN_BABY',mode:'grown',plots:1,count:9,stock:0,nurture:0,interval:24,feed:'T3_WHEAT',feedQty:null,productYield:null,meatYield:18,butcherCost:0,sellBabies:true}));refresh(false);};
 $('island-add-worker').onclick=()=>{if(plan.workers.length>=30)return message('Не больше 30 групп рабочих.');mutate(()=>plan.workers.push({uid:uid(),id:'T5_JOURNAL_WOOD',count:3,yield:100,mode:'buy',stock:0,fillCost:0,fillValue:0,reward:null}));refresh(false);};
 panel.addEventListener('change',e=>{const el=e.target;if(!store)return;if(el.dataset.islandGroup){const group=el.dataset.islandGroup,r=plan[group].find(r=>r.uid===el.dataset.uid);if(!r)return;const key=el.dataset.field;mutate(()=>{if(key==='focus'){if(el.value==='')delete plan.focusCosts[profile()+'|'+r.id];else plan.focusCosts[profile()+'|'+r.id]=Number(el.value);return;}r[key]=el.type==='checkbox'?el.checked:el.tagName==='SELECT'?el.value:el.value===''&&['reward','feedQty','productYield'].includes(key)?null:Number(el.value);if(group==='workers'&&key==='id')r.reward=null;if(group==='animals'&&key==='id'){const a=D.animals.find(x=>x.id===r.id);r.feed=a.favorite;r.feedQty=r.productYield=null;r.meatYield=a.meatYield;r.stock=0;if(r.mode==='produce'&&!a.product)r.mode='grown';}if(group==='animals'&&key==='mode'){r.stock=0;if(r.mode==='produce')r.nurture=0;}if(group==='animals'&&key==='count')r.nurture=Math.min(r.nurture,r.count);if(group==='animals'&&key==='feed')r.feedQty=null;if(group==='crops'&&key==='plots')r.water=Math.min(r.water,r.plots*9);});if(['id','mode','reward','stock','sellSeeds','water','sellBabies','nurture'].includes(key))refresh(false);return;}
  if(el.dataset.islandPrice){mutate(()=>{if(el.value==='')delete plan.prices[el.dataset.islandPrice];else plan.prices[el.dataset.islandPrice]=Number(el.value);});return;}
  if(el.id==='island-actual-from'||el.id==='island-actual-to')return ledger();
  if(el.id.startsWith('island-cap-'))return mutate(()=>{plan.capital[el.id.slice(11)]=Number(el.value);},false);
  const key=el.id.replace(/^island-/,'');if(['city','sellCity','saleMode','plots','houses','slots','days','interval','premium','tax','setup','transport','other','premiumDaily','focusBudget','focusValue'].includes(key)){mutate(()=>{plan[key]=el.type==='checkbox'?el.checked:el.tagName==='SELECT'?el.value:Number(el.value);if(key==='premium'&&[4,8].includes(plan.tax))plan.tax=plan.premium?4:8;},['city','sellCity'].includes(key));if(key==='premium')$('island-tax').value=plan.tax;if(['city','sellCity'].includes(key))refresh(false);}
 });
 panel.addEventListener('click',e=>{const remove=e.target.closest('[data-remove-group]'),entry=e.target.closest('[data-remove-entry]');if(remove){mutate(()=>{plan[remove.dataset.removeGroup]=plan[remove.dataset.removeGroup].filter(r=>r.uid!==remove.dataset.uid);});refresh(false);}if(entry)mutate(()=>{plan.ledger=plan.ledger.filter(x=>x.uid!==entry.dataset.removeEntry);},false);});
 $('island-picker').onchange=e=>{try{store.select(state.server,e.target.value);render();refresh(false);message('Остров выбран.');}catch(error){message(error.message);}};
 function add(copy){try{store.add(state.server,$('island-name').value,copy);render();refresh(false);$('island-name').value='';message(copy?'План скопирован; фактический журнал пуст.':'Остров добавлен.');}catch(error){message(error.message);}}
 $('island-add').onclick=()=>add(false);$('island-copy').onclick=()=>add(true);$('island-rename').onclick=()=>{try{store.rename(state.server,$('island-name').value);render();message('Название сохранено.');}catch(error){message(error.message);}};
 $('island-delete').onclick=()=>{if(!store)return;if(!confirm('Удалить остров «'+current().name+'» вместе с его фактическим журналом?'))return;try{store.remove(state.server);render();refresh(false);message('Остров удалён.');}catch(error){message(error.message);}};
 $('island-actual-date').value=new Date().toLocaleDateString('sv-SE');$('island-actual-form').onsubmit=e=>{e.preventDefault();if(!store)return;const entry={uid:uid(),date:$('island-actual-date').value,note:$('island-actual-note').value.trim()};for(const k of ['income','supplies','fees','transport','other','investment'])entry[k]=Number($('island-actual-'+k).value);if(Object.values(entry).filter(v=>typeof v==='number').every(v=>v===0))return message('Введите хотя бы один доход или расход.');const before=plan.ledger;plan.ledger=[...plan.ledger,entry];if(!save()){plan.ledger=before;return;}ledger();for(const k of ['income','supplies','fees','transport','other','investment'])$('island-actual-'+k).value=0;$('island-actual-note').value='';message('Фактический результат записан.');};
 function download(name,rows){const blob=new Blob([E.csv(rows)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 $('island-export').onclick=()=>{if(!result?.ready)return;download('Albion-island-plan.csv',[['Остров',current().name],['Сервер',state.server],['Город острова',plan.city],['Город продажи',plan.sellCity],['Период дней',plan.days],['Сборов',result.cycles],['Прибыль за период',result.profit],['Стартовые вложения',result.investment],['Первый запуск: нужные деньги',result.requiredCash],['Денежный итог',result.netCash],['Экономическая прибыль',result.economicProfit],['Окупаемость дней',result.payback??'Не рассчитана'],['Источник','Выручка за сбор','Закупки за сбор','Комиссии','Прибыль'],...result.rows.map(r=>[r.name,r.gross,r.cost,r.fees,r.profit])]);};
 $('island-actual-export').onclick=()=>download('Albion-island-actual.csv',[['Остров',current().name],['Сервер',state.server],['Дата','Описание','Выручка','Закупки','Комиссии','Доставка','Другие','Вложения','Чистый денежный поток'],...ledgerEntries().map(e=>[e.date,e.note,e.income,e.supplies,e.fees,e.transport,e.other,e.investment,E.actual([e]).netCash])]);
 $('island-to-actual').onclick=()=>$('island-actual').scrollIntoView({behavior:'smooth',block:'start'});
 document.addEventListener('characterprofilechange',()=>{if(active&&store){rows();results();}});
 window.IslandUI={active:()=>active,snapshot:()=>JSON.parse(JSON.stringify({server:state.server,plan,current:store?current():null,result})),refresh};
})();
